 x['warning_lines']=[line for line in (text+'\n'+err).splitlines() if 'Warning:' in line or re.search(r'^warning(?:\[|:)',line)];x['actual_error_lines']=[line for line in (text+'\n'+err).splitlines() if re.search(r'^error(?:\[|:)',line)];commands.append(x)
