headers=[line.strip() for line in e.splitlines() if line.strip().startswith(('Running ','Doc-tests '))];assert len(headers)==len(matches)==17
suites=[dict(target=h,passed=int(m[0]),failed=int(m[1]),ignored=int(m[2])) for h,m in zip(headers,matches)]
